def spiral2(seed,H,W,first_idx,L0):
    order=[(-1,0),(0,1),(1,0),(0,-1)]  # up,right,down,left
    out={seed}; cur=seed; L=L0
    for k in range(30):
        d=order[(first_idx+k)%4]
        for _ in range(L):
            ni,nj=cur[0]+d[0],cur[1]+d[1]
            if not(0<=ni<H and 0<=nj<W): return out
            cur=(ni,nj); out.add(cur)
        L+=2 if k%2 else 0
    return out
